import{_ as a,o as s,c as t,ai as i}from"./chunks/framework.Ci0kozOl.js";const p=JSON.parse('{"title":"Performance & Scalability","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/advanced/performance-scalability.md","filePath":"3.0/advanced/performance-scalability.md","lastUpdated":1786019473000}'),n={name:"3.0/advanced/performance-scalability.md"};function o(r,e,l,h,d,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="performance-scalability" tabindex="-1">Performance &amp; Scalability <a class="header-anchor" href="#performance-scalability" aria-label="Permalink to &quot;Performance &amp; Scalability&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>UnoPim is built for catalogs in the millions. Much of that work happens automatically — the platform paginates, indexes, queues, and caches its own hot paths so that a large catalog behaves like a small one.</p><p>Sometimes, though, you may wish to tune the platform for your own workload, or you may be writing extension code that must stay fast at scale. This page covers both: what UnoPim does for you out of the box, the knobs you can turn, and the rules your own code should follow.</p><p>We will begin with the platform&#39;s built-in behavior, then look at Elasticsearch, queues, and Octane, and finish with the extension rules and a tuning checklist for reference.</p><h2 id="what-the-platform-does-for-you" tabindex="-1">What the Platform Does for You <a class="header-anchor" href="#what-the-platform-does-for-you" aria-label="Permalink to &quot;What the Platform Does for You&quot;">​</a></h2><p>On large product exports and completeness collection, UnoPim uses <strong>keyset pagination</strong> instead of offset pagination — <code>OFFSET</code> degrades badly at depth, while a <code>WHERE id &gt; ?</code> cursor does not. The REST API exposes the same idea as <a href="./../api/whats-new-v3.html#delta-synchronization"><code>search_after</code> pagination</a>.</p><p>The 3.0 migrations add <strong>hot-path indexes</strong> covering products, completeness, attribute-family mappings, and lookup-heavy catalog relations, so the queries the admin runs most often are always index-backed.</p><p>Product mass delete and status changes above a threshold run as <strong>queued mass actions</strong> instead of blocking the admin request. You may adjust the threshold in your environment file:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">PRODUCT_MASS_ACTION_ASYNC_THRESHOLD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">200</span></span></code></pre></div><p>The product edit screen loads <strong>attribute groups lazily</strong> with a persistent sidebar, so a 500-attribute family renders instantly. REST responses for slow-changing entities (attributes, families, locales, and so on) are served from a <strong>versioned structure cache</strong> with automatic invalidation (<a href="./../api/whats-new-v3.html">details</a>).</p><p>During indexing, <strong>bounded Elasticsearch bulk requests</strong> and isolated query-builder state prevent memory spikes and concurrent filter leakage. And rather than counting per request, <strong>dashboard aggregates</strong> are precomputed by <code>unopim:dashboard:refresh</code>, which runs every 10 minutes.</p><h2 id="elasticsearch-is-optional-—-both-paths-must-work" tabindex="-1">Elasticsearch Is Optional — Both Paths Must Work <a class="header-anchor" href="#elasticsearch-is-optional-—-both-paths-must-work" aria-label="Permalink to &quot;Elasticsearch Is Optional — Both Paths Must Work&quot;">​</a></h2><p>Search and grid filtering branch on <code>config(&#39;elasticsearch.enabled&#39;)</code>. When Elasticsearch is enabled, grids and filters run against the index — which is updated asynchronously, so you should never assume a write is searchable in the same request. When it is disabled, the same features run against the database.</p><p>If you write extension filters, you must implement both branches. Register them through the <code>unopim.database.attribute.filters</code> and <code>unopim.elasticsearch.attribute.filters</code> container tags, and keep the result shape, ordering, and pagination identical across the two paths.</p><h2 id="queues" tabindex="-1">Queues <a class="header-anchor" href="#queues" aria-label="Permalink to &quot;Queues&quot;">​</a></h2><p>Heavy work belongs on queues. UnoPim uses named queues so each workload class can be scaled independently: the <code>system</code> queue carries imports, exports, and mass actions; <code>completeness</code> carries completeness recalculation; <code>publication</code> carries passport publishing, bulk transitions, and view analytics; <code>webhooks</code> carries webhook delivery; and <code>default</code> carries everything else.</p><p>A single worker can drain them all:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;system,completeness,publication,webhooks,default&quot;</span></span></code></pre></div><p>In production, you should use Redis (<code>QUEUE_CONNECTION=redis</code>), and if any queue backs up, run one worker set per workload class.</p><h2 id="octane" tabindex="-1">Octane <a class="header-anchor" href="#octane" aria-label="Permalink to &quot;Octane&quot;">​</a></h2><p>The codebase is Octane-safe: no request state lives in singletons (scoped bindings like <code>CatalogScope</code> and <code>SsoManager</code> reset per request), token TTLs use relative intervals, and configuration reads are cache-driver-consistent. If you run Octane, your extensions must follow the same rules — never memoize request data in a static or a singleton.</p><h2 id="rules-for-extension-code" tabindex="-1">Rules for Extension Code <a class="header-anchor" href="#rules-for-extension-code" aria-label="Permalink to &quot;Rules for Extension Code&quot;">​</a></h2><p>These are the failure modes that actually reach production on large catalogs, so treat them as hard rules rather than suggestions:</p><ol><li><strong>Never <code>-&gt;get()</code> an unbounded set.</strong> Iterate with <code>chunkById()</code> / <code>lazyById()</code>; prefer <code>cursorPaginate()</code> on hot grids.</li><li><strong>Push work into SQL.</strong> No filtering, summing, or de-duplicating large collections in PHP.</li><li><strong>No queries in loops or views.</strong> Eager load with constrained selects.</li><li><strong>Index what you filter, sort, or join on</strong> — in the same migration as the feature; check for an existing index first.</li><li><strong>Bulk write</strong> with <code>upsert()</code> / chunked <code>insert()</code>, not per-row saves.</li><li><strong>Queue anything unbounded and user-triggered</strong> (imports, recalculations, republishing) with a batch size.</li><li><strong>Cache expensive counts</strong> — a <code>count()</code> on a million-row table for a UI badge is a slow query.</li><li><strong>Stay engine-portable</strong> — the same code must run on MySQL 8 and PostgreSQL 16; let the query builder emit JSON paths and quote identifiers (<code>DB_PREFIX</code> installations break on interpolated table names).</li></ol><h2 id="tuning-checklist" tabindex="-1">Tuning Checklist <a class="header-anchor" href="#tuning-checklist" aria-label="Permalink to &quot;Tuning Checklist&quot;">​</a></h2><p>For reference, these are the environment variables that most directly affect performance:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">PRODUCT_MASS_ACTION_ASYNC_THRESHOLD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">200   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># queue mass actions above this</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">UNOPIM_API_STRUCTURE_CACHE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">true           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># REST structure cache</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">UNOPIM_API_STRUCTURE_CACHE_TTL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">3600</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">REST_API_RATE_LIMIT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">120                   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># protect the API tier</span></span></code></pre></div><p>Beyond the environment file, a few infrastructure defaults serve large catalogs well:</p><ul><li>PHP: <code>memory_limit=4G</code>, OPcache enabled, <code>max_execution_time=360</code> for CLI imports</li><li>Redis for cache, sessions, and queues</li><li>Elasticsearch heap sized to the document count; keep 15% disk free</li><li>Run <code>unopim:product:index</code> after bulk imports rather than relying on per-save indexing</li></ul>`,30)])])}const g=a(n,[["render",o]]);export{p as __pageData,g as default};
